H.background();
const dH = P.dH, dS = P.dS, T = Math.max(0, P.T);
// dH in kJ/mol, dS in J/(mol K) -> convert dS to kJ for dG in kJ/mol
const dG = dH - T * (dS / 1000);
const v = H.plot2d({ xMin: 0, xMax: 1000, yMin: -250, yMax: 250 });
v.grid(); v.axes();
// dG(T') as a line across the temperature axis: dG = dH - T'*(dS/1000)
v.fn(Tx => dH - Tx * (dS / 1000), { color: H.colors.accent, width: 3 });
// zero line (spontaneity boundary)
v.line(0, 0, 1000, 0, { color: H.colors.axis, width: 1, dash: [5, 5] });
// sweeping temperature marker
const Tm = 500 + 480 * Math.sin(t * 0.5);
const dGm = dH - Tm * (dS / 1000);
v.line(Tm, -250, Tm, 250, { color: H.colors.sub, width: 1, dash: [3, 3] });
v.dot(Tm, dGm, { r: 7, fill: dGm < 0 ? H.colors.good : H.colors.warn });
v.text(dGm < 0 ? "spontaneous" : "non-spont.", Tm, dGm + (dGm < 0 ? -25 : 25));
H.text("Gibbs free energy:  dG = dH - T*dS", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
